cards.code:
@layer base, components;
@layer base { button { color: #143d2b; } }
@layer components { .save { color: #075985; } }

body { font-family: system-ui, sans-serif; line-height: 1.6; }
.article { max-inline-size: 65ch; }
.article h2 { font-weight: 700; text-wrap: balance; }

.bed-panel { container-type: inline-size; }
.bed-summary { display: grid; gap: 1rem; }
@container (min-width: 30rem) { .bed-summary { grid-template-columns: 1fr 1fr; } }

.save { transition: transform 150ms ease; }
.save:hover { transform: translateY(-2px); }
@media (prefers-reduced-motion: reduce) {
  .save { transition: none; }
  .save:hover { transform: none; }
}

@keyframes reveal { from { opacity: 0; } to { opacity: 1; } }
.notice { animation: reveal 200ms ease-out; }
@media (prefers-reduced-motion: reduce) { .notice { animation: none; } }

.btn.garden-action {
  --bs-btn-bg: #166534;
  --bs-btn-border-color: #166534;
  --bs-btn-hover-bg: #14532d;
  --bs-btn-hover-border-color: #14532d;
}

@import "tailwindcss";
@theme {
  --color-garden: #166534;
  --font-journal: Georgia, serif;
}

.field { border: 2px solid transparent; }
.field:has(> input:invalid) { border-color: crimson; }
.field :is(input, select) { padding: 4px; }

@layer base, theme;
@layer base { .action { color: navy; } }
@layer theme { .action { color: red; } .action.plain { color: revert-layer; } }

.panel { color: green; }
.panel span { margin-left: 12px; }
.initial { color: initial; }
.panel .unset { color: unset; margin-left: unset; }
.revert { display: flex; display: revert; }

.reader { width: min(100%, 600px); }
.reader h2 { font-size: clamp(20px, 4vw, 40px); margin: 0; }
.reader aside { width: max(120px, 25%); }

.toolbar { display: flex; width: 240px; }
.title { flex: 1 1 0; min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.action { flex: 0 0 60px; }

.row { display:flex; width:300px; }
.primary { flex:2 1 0; min-width:0; }
.secondary { flex:1 1 0; min-width:0; }

.component { position:relative; z-index:1; }
.tooltip { position:absolute; width:100px; height:100px; z-index:9999; background:red; }
.overlay { position:absolute; top:0; left:0; width:100px; height:100px; z-index:2; background:blue; }

.scroll { height:100px; overflow:auto; }
.heading { position:sticky; top:0; height:20px; background:white; }
.content { height:300px; }

.table-scroll { width:180px; overflow:auto; }
table { border-collapse:separate; border-spacing:0; width:400px; table-layout:fixed; }
th { width:100px; position:sticky; left:0; background:white; }

@keyframes drift { to { transform:translateX(20px); } }
.indicator { animation:drift 1s linear infinite alternate; }
@media (prefers-reduced-motion:reduce) { .indicator { animation:none; } }

:root { color-scheme:light dark; }
.control { border:2px solid currentColor; }
.control:focus-visible { outline:3px solid currentColor; outline-offset:2px; }
@media (forced-colors:active) { .control { border-color:ButtonText; } .control:focus-visible { outline-color:Highlight; } }

.manual { counter-reset:section; }
.chapter { counter-increment:section; }
.chapter::before { content:counter(section) ". "; }

.panel { opacity:0; transition:opacity 200ms linear; }
.panel.open { opacity:1; }
@media (prefers-reduced-motion:reduce) { .panel { transition:none; } }

@keyframes enter { from { opacity:0; transform:translateY(10px); } to { opacity:1; transform:translateY(0); } }
.notice { animation:enter 1s linear both; }
@media (prefers-reduced-motion:reduce) { .notice { animation:none; } }

.actions { display:flex; gap:8px; flex-direction:column; }
@media (min-width:768px) { .actions { flex-direction:row; } }
.actions .btn { --bs-btn-bg:#166534; --bs-btn-border-color:#166534; --bs-btn-hover-bg:#14532d; --bs-btn-hover-border-color:#14532d; --bs-btn-disabled-bg:#166534; --bs-btn-disabled-border-color:#166534; }

@import "tailwindcss";
@source inline("md:grid-cols-2");
@theme { --color-harvest:#166534; }
.recipe { @apply grid grid-cols-1 gap-4; }
@media (min-width:48rem) { .recipe { @apply md:grid-cols-2; } }
.recipe button { @apply bg-harvest text-white p-2; }
.recipe button:focus-visible { @apply outline-2 outline-offset-2 outline-harvest; }

.shrink-row { display:flex; width:240px; }
.wide { flex:0 1 200px; min-width:0; }
.narrow { flex:0 1 100px; min-width:0; }

.minimum { width:min-content; }
.maximum { width:max-content; }
.minimum, .maximum { font:20px/1 monospace; }
